/* generat de tools/i18n25/hub-i18n.mjs din data/hub-i18n/apps/sq.json — nu edita de mână */
__hubApps("sq",{"FreeDetect":{"line":"Dëshironi të kontrolloni nëse një tekst duket i shkruar ose i kopjuar nga inteligjenca artificiale? 42 mjete të jashtme dhe një gjenerues citimesh në një vend. Vetë aplikacioni nuk zbulon asgjë.","detail":"Panel me 42 mjete të jashtme për zbulimin e inteligjencës artificiale/plagjiaturës dhe një gjenerues citimesh (verifikon ISBN). Nuk zbulon asgjë vetë në pajisje; ndihmon në kontrollin e referencave.","tags":["katalog","citime"]},"Arhiva-fara-frontiere":{"line":"Shfletoni koleksionet e Internet Archive pa llogari: kërkim, faqe artikujsh, parapamje dhe të preferuarat. Jozyrtar; archive.org e shikon adresën tuaj IP dhe kërkimet.","detail":"Shfletues jozyrtar për koleksionet e Internet Archive (kërkim, faqe artikujsh, parapamje, të preferuarat dhe kërkimet e fundit të ruajtura lokalisht), pa llogari. Nuk kërkon në Wayback Machine; archive.org merr IP-në dhe kërkimet tuaja.","tags":["arkiva web","burime"]},"AcademiSearch":{"line":"Një kërkim — artikuj shkencorë nga dhjetëra burime të hapura. Listën mund ta ruani për citim. Kërkon internet; kërkesat shkojnë te këto shërbime.","detail":"Meta-kërkim akademik në 11 API të hapura (OpenAlex, Crossref, arXiv etj.) plus lidhje me portale; eksport BibTeX/RIS/CSV. Kërkon internet; kërkimet tuaja shkojnë te ato shërbime.","tags":["literaturë","burime"]},"Surveyor":{"line":"Çfarë lidhjesh ka faqja juaj dhe cilat nuk funksionojnë? I rendit me spirancat dhe ridrejtimet. Të jashtmet nuk verifikohen me siguri. Vetëm për faqet tuaja.","detail":"Inventarizon lidhjet e një faqeje (HTML statik, ndërfaqe në anglisht), përfshirë spiancat dhe ridrejtimet. Lidhjet e jashtme nuk mund të konfirmohen nga shfletuesi (CORS); dërgon kërkesa; kontrolloni vetëm faqet tuaja.","tags":["lidhje të vdekura","auditim"]},"Trade-Free-Link-Guardian":{"line":"Për faqen tuaj në WordPress: gjen lidhje të prishura dhe i rregullon pa shërbime të jashtme. Ndryshon përmbajtje reale, ndaj bëni më parë një kopje rezervë. Nuk është provuar në një WordPress të vërtetë.","detail":"Shtojcë WordPress që kontrollon lidhjet dhe riparon në mënyrë deterministe ato të prishura, pa shërbim të jashtëm. Modifikon përmbajtje reale: bëni një kopje rezervë. Nuk është testuar në një WordPress real.","tags":["WordPress","GPL v2"]},"OUTPOST":{"line":"Ndiqni faqet tuaja dhe shihni nëse ende përgjigjen. Funksionon vetëm për sa kohë skeda mbetet e hapur. Edhe një faqe me gabim llogaritet si përgjigje. Ndërfaqja është në anglisht.","detail":"Monitor i arritshmërisë brenda shfletuesit: kontrollon nëse faqet tuaja përgjigjen (nuk lexon kodin e statusit HTTP; 404/500 llogariten si përgjigje). Vetëm kur skeda është e hapur. Ndërfaqe në anglisht.","tags":["monitorim"]},"ScryVeil":{"line":"Kontrolloni sigurinë e një domeni dhe merrni një raport teksti që mund ta ruani. Disa kontrolle mund të jenë të paplota ose të kërkojnë çelës. Lidhet me shërbime të palëve të treta; vetëm për domenet tuaja.","detail":"Diagnostikim sigurie për një domen (DNS, RDAP, certifikata), me raport tekstual të eksportueshëm; kontrollet e kokave dhe të reputacionit shpesh bllokohen ose kërkojnë çelës. Kontakton palë të treta; vetëm për domene që zotëroni.","tags":["OSINT","siguri"]},"Vitrina":{"line":"Fusni një postim publik të Facebook-ut në faqen tuaj pa llogari dhe kopjoni kodin e gatshëm. Jozyrtar; Meta e shikon IP-në tuaj, shfaqja nuk garantohet.","detail":"Ngulit faqe/postime publike të Facebook-ut përmes shtojcave të Meta-s, jozyrtare; kopjon kodin e ngulitjes. “Pa llogari” nuk do të thotë “pa gjurmim”: Meta e sheh IP-në tuaj; shfaqja nuk garantohet.","tags":["ndjekje burimesh"]},"Threads-fara-cont":{"line":"Lexoni postime publike të Threads pa llogari dhe ruajini si tekst. Jozyrtar; Meta e shikon IP-në tuaj, ndonjëherë nevojitet një ndërmjetës.","detail":"Shfaq postime publike të Threads përmes ngulitjes së Meta-s, pa llogari; ruajtje lokale opsionale, eksport .txt. Meta e sheh IP-në tuaj; mund të kërkojë një ndërmjetës CORS. Jozyrtar.","tags":["ndjekje burimesh"]},"X-fara-cont":{"line":"Hyni në profile dhe postime publike në X pa llogari në disa mënyra: lidhje e drejtpërdrejtë, arkiv, kërkim ose Nitter. Nuk e lexon përmbajtjen; e dërgon lidhjen te archive.org.","detail":"Gjeneron shtigje aksesi pa llogari për profile dhe postime publike të X: lidhje e drejtpërdrejtë, arkivë Wayback, kërkim, Nitter. Nuk e lexon përmbajtjen; i dërgon archive.org emrin e përdoruesit/lidhjen.","tags":["ndjekje burimesh"]},"Arhiva-LinkedIn":{"line":"Mbani në një vend shënime për postimet e LinkedIn që i keni ngjitur vetë dhe eksportojini si tekst. Galeria përdor ngulitjen zyrtare, prandaj lidhet me LinkedIn. Jozyrtar.","detail":"Arkiv shënimesh për postime LinkedIn të ngjitura dorazi (import CSV, eksport Markdown) + një galeri përmes ngulitjes zyrtare të LinkedIn (kontakton LinkedIn). Jozyrtar.","tags":["arkivim"]},"Cadraj":{"line":"Mblidhni klipe të TikTok-ut me dorë, të grupuara sipas autorit, dhe shikojini në luajtësin zyrtar. Mund të shënoni ato që i keni parë tashmë.","detail":"Koleksion manual klipesh TikTok sipas autorit, të luajtura përmes lojtarit zyrtar; shenjë “parë”.","tags":["ndjekje burimesh"]},"FASCICUL":{"line":"I kthen telefonat në një dhomë në një tabelë të përbashkët në videoprojektor: vizatime, shënime, imazhe, tregues lazer dhe kamerë e drejtpërdrejtë. Provuar në kompjuter; në telefona realë ende nuk është konfirmuar.","detail":"Telefona ↔ projektor video: një tabelë e përbashkët me vizatim, shënime, imazhe, tregues lazer dhe kamerë të drejtpërdrejtë, në një skedar të vetëm. Lidhje e drejtpërdrejtë WebRTC në rrjetin lokal, pa server të palës së tretë; ndërmjetës opsional në telefonin hotspot (Android/Termux). Testuar në Chromium; ende i paverifikuar në telefona realë.","tags":["bashkëpunim"]},"INDICATIV":{"line":"Përgatituni për provimin e radioamatorëve ANCOM pa internet: 723 pyetje me përsëritje të shpërndarë. Jozyrtar; banka e pyetjeve është verifikuar vetëm pjesërisht.","detail":"Trajner jozyrtar, offline, për provimin e radioamatorëve të ANCOM (723 pyetje, përsëritje e hapësuar, kërkim në bankën e pyetjeve). Nuk është material i ANCOM; banka e pyetjeve është verifikuar vetëm pjesërisht.","tags":["provim","radio"]},"ETER":{"line":"Mësoni radioamatorizëm në një enciklopedi: alfabeti Morse, stërvitës, llogaritës antenash dhe kërkim në të gjithë përmbajtjen.","detail":"Enciklopedi e radioamatorizmit: Morse, trajner Koch, kalkulatorë antenash, kërkim global.","tags":["radio","enciklopedi"]},"ATINGERE":{"line":"E kthen një libër në Brailë me dridhje në ekranin me prekje për të shurdhër-verbrit ose në audiolibër për të verbrit. Nuk është verifikuar me lexues të Brailës; ka kufizime.","detail":"Shndërron libra në braj prekës ose audiolibra. I pavlerësuar nga lexues vendas; shihni kufizimet në README.","tags":["aksesueshmëri"]},"Clopotel":{"line":"Mbani kohën në një konferencë ose punishte: kohëmatës skene me programin tuaj dhe sinjal kur po afrohet fundi. Në rumanisht dhe anglisht.","detail":"Kohëmatës skene me axhendë folësish (import tekst/CSV) dhe sinjal paralajmërues, RO/EN.","tags":["ngjarje","MIT"]},"Monstrarium":{"line":"Planifikoni një punishte për krijimin e përbindëshave nga materiale të riciklueshme: aplikacioni llogarit materialet dhe seancat, ofron 50 përbindësha me zë, 3D dhe lojë edukative.","detail":"Planifikues për një punishte përbindëshash nga materiale të riciklura: llogarit vetë materialet, orar sipas serive, 50 përbindësha origjinalë me tinguj, 3D dhe një lojë edukative.","tags":["punishte","MIT"]},"TranslateHub":{"line":"Zgjidhni mes 22 mjeteve të përkthimit ose përktheni me inteligjencë artificiale me çelësin tuaj. Teksti i përkthyer me IA shkon te shërbimi i Anthropic.","detail":"Katalog me 22 mjete përkthimi plus një përkthyes AI me çelësin tuaj. Teksti AI dërgohet te api.anthropic.com.","tags":["përkthim","IA"]},"DataWeave":{"line":"Hapni një tabelë dhe kuptojeni: statistika, grafikë, tabela kryesore dhe korrelacione. Të dhënat tuaja mbeten në pajisjen tuaj.","detail":"Eksploroni CSV/TSV/JSON në një skedar të vetëm: tabelë, statistika, grafikë, pivot dhe korrelacione; të dhënat mbeten në pajisjen tuaj.","tags":["të dhëna"]},"MarkdownAtelier":{"line":"Shkruani dokumente në Markdown dhe shihni menjëherë si duken, me formula të thjeshta; në 7 gjuhë, pa internet. Tekstet mbeten në shfletuesin tuaj; ruani një kopje rezervë.","detail":"Redaktor Markdown offline me parapamje, GFM, një nënbashkësi LaTeX (MathML), 7 gjuhë, kërkim dhe kopje rezervë .json. Dokumentet mbeten në shfletues.","tags":["shkrim"]},"RegexLab":{"line":"Provoni një shprehje të rregullt dhe shihni menjëherë çfarë kap; shpjegime hap pas hapi, teste dhe paralajmërim nëse mund ta ngrijë programin.","detail":"Testim shprehjesh të rregullta JavaScript me shpjegime, teste dhe alarm ReDoS.","tags":["zhvillim"]},"SEOptimum":{"line":"Kontrolloni sa gati është një faqe web për motorët e kërkimit. 20 mjete, përfshirë analizën e faqes dhe parapamjen e mënyrës si do të shfaqet në rezultatet e kërkimit.","detail":"20 mjete SEO brenda shfletuesit: analizë në faqe, parapamje SERP.","tags":["web"]},"SEVA":{"line":"Mësoni për gjumin, ritmin ditor të trupit, frymëmarrjen dhe ushqimin në një enciklopedi që mund ta dëgjoni edhe. Vetëm informuese; nuk është këshillë mjekësore.","detail":"Enciklopedi mirëqenieje: gjumi, ritmi cirkadian, frymëmarrja, ushqyerja; dëgjim me zë të lartë. Informuese; nuk është këshillë mjekësore.","tags":["shëndet"]},"PULS":{"line":"Çfarë të bëni derisa të vijë ambulanca? Udhëzues rumun për ndihmën e parë me metronom për ringjalljen dhe kartë opsionale emergjence. Klinikisht i paverifikuar; telefononi 112.","detail":"Udhëzues ndihme së parë në rumanisht (CPR me metronom, garrot), me kërkim dhe kartë emergjence opsionale. Përmbajtja nuk është vlerësuar klinikisht nga specialist; nuk zëvendëson një kurs të autorizuar. Në urgjencë, telefononi 112.","tags":["shëndet","urgjenca"]},"VATRA":{"line":"Çfarë të bëni nëse në natyrë mbaroni nga uji, zjarri ose strehimi? Enciklopedi mbijetese pa internet, me kërkim dhe shënime. Vetëm për edukim; në urgjencë telefononi 112.","detail":"Enciklopedi mbijetese offline (ujë, zjarr, strehë, orientim), me kërkim dhe shënime të ruajtura lokalisht. Material edukativ, nuk zëvendëson një kurs ndihme së parë; në urgjencë telefononi 112.","tags":["punë në terren"]},"Eclipsa-2027":{"line":"Shikoni në hartë pa internet ku dhe sa zgjat eklipsi i plotë diellor i 2 gushtit 2027, me qytete dhe kërkim vendi. Vlerat janë orientuese; mos e shikoni Diellin pa filtër.","detail":"Hartë offline e eklipsit total të 2 gushtit 2027, me kohëzgjatje, mbulim sipas qytetit dhe kërkim vendesh. Vlera orientuese; mos e shikoni Diellin pa filtra të certifikuar.","tags":["astronomi"]},"orarium":{"line":"Sa është ora tani në Mars, në Hënë ose në një asteroid? Ora lokale drejtpërdrejt në 45 trupa qiellorë. Model i përafërt, nuk nevojitet internet; jo për navigim.","detail":"Koha në çdo botë: ora lokale e drejtpërdrejtë në 45 trupa (Hëna, Marsi, planetët, hënat, asteroidët), shpejtësia e orës kundrejt Tokës, distanca dhe koha e shkuarjes-ardhjes së sinjalit, konvertues zonash orare dhe harta kolonizimi. Model orientues, offline; jo për navigim. Përfshin mesnatën dhe mesditën në çdo trup, dritaret e transmetimit Tokë–trup dhe një lidhje me TerRa.","tags":["astronomi","koha"]},"TerRa":{"line":"Glob 3D dhe hartë që tregojnë ditën dhe natën në Tokë, në Hënë dhe në planetë. Pozicionet e satelitëve mund të vonojnë rreth 3 muaj derisa t'i përditësoni online.","detail":"Glob dhe hartë 3D: terminatori, Hëna, planetët. Satelitët përdorin një pamje të vjetruar (~3 muaj) offline; për pozicione aktuale, përditësoni online. Lidhje unike për çdo pamje; qielli nga cilido prej 45 trupave të ORARIUM, i lidhur në të dyja drejtimet.","tags":["astronomi"]},"Horizons.BeyondLimits":{"line":"Udhëtoni nëpër historinë e Universit nga Big Bengu deri në fund përmes 91 pikave kyçe. E ardhmja është spekulim shkencor, jo parashikim i saktë.","detail":"Hartë kronologjike nga Big Bengu deri në fundin e universit: 91 ngjarje, eksport Markdown; e ardhmja është spekulative, jo parashikim i vlerësuar.","tags":["kozmologji"]},"Hyper4D":{"line":"Shikoni si duken format katërdimensionale: rrotulloni ato në ekran dhe vëzhgojini nga disa kënde. Imazhet mund të ruhen.","detail":"Gjeometri 4D në SVG: prerje 3D të trupave dhe politopeve 4D me projeksione 4D→3D→2D të rrotulluara në kohë reale, eksport SVG.","tags":["matematikë"]},"ExploratoriiEco":{"line":"Udhëzues terreni për dashamirët e natyrës: nga klasifikimi i qenieve të gjalla dhe gjurmët te biomet e Rumanisë, ditar vëzhgimesh, etikë dhe urgjenca.","detail":"Udhëzues terreni për natyralistë në 20 seksione: klasifikimi i jetës, shenja dhe gjurmë, biomet e Rumanisë, kalkulatorë, ditar, etikë, emergjenca dhe fjalor.","tags":["natyrë"]},"FieldObserver":{"line":"Shënoni vëzhgimet tuaja në terren; leximet e sensorëve të telefonit shtohen automatikisht. Mbani një arkiv të daljeve tuaja.","detail":"Ditar vëzhgimi në terren me sensorët e telefonit; arkivë, eksport JSON/CSV.","tags":["punë në terren"]},"VietAR":{"line":"Fotografoni ose regjistroni një bimë apo krijesë dhe merrni një ide mes 519 llojeve nga Rumania. Mund të gabojë; mos hani asgjë mbi këtë bazë.","detail":"Identifikim orientues i 519 llojeve rumune nga imazhi/zëri; mund të gabojë, mos hani bimë ose kërpudha mbi bazën e tij. Modelet shkarkohen nga palë të treta; jo plotësisht offline.","tags":["biodiversitet"]},"VOIAJOR":{"line":"Ndiqni trajektoret e Voyager 1 dhe 2 nga viti 1977 deri një miliard vjet përpara, në çdo shkallë — nga planetët te Rruga e Qumështit. Model orientues, jo për navigim.","detail":"Simulim i trajektoreve të Voyager 1 dhe 2 (nga 1977 deri mbi një miliard vjet): harqe balistike midis kalimeve reale pranë planetëve, ekstrapolim me gravitetin diellor dhe dinamikën galaktike lokale, heliosfera, reja e Oortit dhe 19 yje të afërt me lëvizje të vet.","tags":["Voyager","simulim"]},"Nemurirea":{"line":"Zbuloni si plaket trupi dhe çfarë thotë shkenca për orët biologjike dhe jetëgjatësinë, pastaj provoni veten me një kuiz. Nuk është këshillë mjekësore.","detail":"Ese interaktive për orët biologjike dhe shkencën e jetëgjatësisë, me kuiz përfundimtar. Qëllim informues, jo këshillë mjekësore.","tags":["biologji"]},"IncredibleCosmos":{"line":"Vendosni planetë dhe yje që gravitacioni i tyre ta drejtojë një kometë drejt objektivit. 108 nivele, tri vështirësi dhe deri në tri yje për nivel.","detail":"Enigmë graviteti: vendosni planetë dhe yje që graviteti i tyre ta drejtojë një kometë drejt objektivit; 108 nivele në 12 kategori, tri vështirësi, vlerësim 1–3 yje, me kërkim.","tags":["lojë","fizikë"]},"Cupa-Mondiala-2026":{"line":"Luani në Kupën e Botës 2026 dhe ndiqni zhvillimin e një turneu imagjinar. Rezultatet janë të rastësishme, jo parashikim; jozyrtar.","detail":"Simulator fiktiv, jozyrtar i Kupës së Botës 2026: rezultate të rastësishme, jo parashikime; i palidhur me FIFA-n.","tags":["simulim","jozyrtar"]},"AGORA":{"line":"Si lindi euro dhe çfarë do të thotë për Rumaninë? 59 kapituj nga Mastrihti te BQE, plus këshilla për udhëtarët. Jozyrtar.","detail":"Atlas informues i zonës së euros në 59 seksione: nga Mastrihti dhe BQE te Rumania dhe euroja, plus një udhëzues për udhëtarët. Jozyrtar, pa vlerë juridike.","tags":["ekonomi","BE"]},"URME":{"line":"Përgatituni për ecje në shtegun Colți–Aluniș në Buzău: bimë, qelibar, fosile, orë lindjeje dhe perëndimi, pajisje. Harta nuk është për navigim.","detail":"Udhëzues informues, jozyrtar, për ecje në Colți–Aluniș (bimë, qelibar, fosile), me lindjen/perëndimin e Diellit dhe listë pajisjesh. Hartë skematike, jo për navigim; nxjerrja nga zona e mbrojtur është e ndaluar.","tags":["natyrë","Buzău"]},"Belot-fara-frontiere":{"line":"Njihuni me belotin dhe lojërat e ngjashme në vende të tjera, pastaj luani në tryezë: ju dhe një partner IA kundër dy kundërshtarëve IA. Blloku i pikëve përfshihet.","detail":"Atlas i familjes belote/bela/klaverjas/jass dhe lojë me 4 lojtarë (ju dhe një partner AI kundër dy kundërshtarëve AI); belot-i rumun është prioritar; fletë pikësh.","tags":["letra","IA"]},"Scopone-fara-frontiere":{"line":"Mësoni si lindi scopone, cilat janë rregullat e saj dhe si ndryshojnë nga rajoni në rajon, pastaj luani kundër kompjuterit që di të japë këshilla.","detail":"Atlas i Scopone-s (15 fletë: origjina, rregullat, dallimet rajonale) dhe lojë kundër një AI lokale (heuristike / Monte-Carlo), me sugjerime; letra italiane ose franceze.","tags":["letra","IA"]},"Solitaire-fara-frontiere":{"line":"Shfletoni dhe luani pasjanca si Klondike, FreeCell ose Spider. Kur ngecni, kërkoni një ndihmë ose lëreni kompjuterin ta zgjidhë.","detail":"Atlas i lojërave solitaire (Klondike, FreeCell, Spider e të tjera) mbi një motor të përbashkët; “Sugjerim” nga një zgjidhës me kufi nyjesh/kohe dhe zgjidhje automatike opsionale.","tags":["letra"]},"Sudoku-fara-frontiere":{"line":"136 lloje sudoku — nga klasiku te killer dhe 3D; shfletoni dhe luani. Ndihmon me shpjegime hap pas hapi dhe zgjidh enigmat tuaja.","detail":"Atlas me 136 variante Sudoku (klasik, killer, jigsaw, greko-latin, 3D e shumë të tjera), me gjenerues zgjidhjesh unike, zgjidhje hap pas hapi të shpjeguar, 7 mënyra loje dhe zgjidhës.","tags":["enigma"]},"Domino-fara-frontiere":{"line":"Mësoni historinë dhe rregullat e dominos, pastaj luani në tryezë kundër një deri në tre kundërshtarëve të drejtuar nga kompjuteri. Lëvizja mund të zhbëhet.","detail":"Atlas domino (origjina, rregullat, përafrimet) dhe tavolinë loje kundër 1–3 lojtarëve AI, me tri nivele; zhbërje e lëvizjes.","tags":["domino","IA"]},"Mahjong-fara-frontiere":{"line":"Njihuni me 8 lloje mahjong-u; luani pasjansë ose lojë me katër veta me tre kundërshtarë të thjeshtë të drejtuar nga kompjuteri. Funksionon pa internet.","detail":"Atlas me 8 variante mahjong, solitaire dhe mahjong me 4 lojtarë (riichi, Hong Kong, Sichuan) kundër 3 AI të thjeshta heuristike. Offline.","tags":["mahjong","IA"]},"Go-fara-frontiere":{"line":"Mësoni nga vjen go dhe si luhet, pastaj provoni veten kundër kompjuterit që di të japë këshilla. Nuk dërgon asnjë të dhënë përmes internetit.","detail":"Atlas i Go (18 fletë: origjina, rregullat, përafrimet) dhe lojë kundër një AI lokale (Monte-Carlo, jo LLM), me SGF dhe sugjerime; pa kërkesa rrjeti.","tags":["go","IA"]},"Zaruri-fara-frontiere":{"line":"26 lojëra me zare që mund t'i lexoni, 12 prej tyre kundër kompjuterit; plus një simulator hedhjesh me probabilitete. Pa para; jashtë linje.","detail":"Atlas me 26 lojëra me zare; 12 të luajtshme kundër një AI didaktike (jo LLM), plus një simulator NdM me probabilitete të sakta. Nuk është lojë fati me para; offline.","tags":["zare"]},"Sah-fara-frontiere":{"line":"Mbi 700 variante shahu për t'i eksploruar dhe një fjalor i vogël termash; shumicën mund t'i luani kundër kompjuterit. Funksionon pa internet.","detail":"706 hyrje variantesh shahu (vetëm disa me burim të verifikuar; disa sintetike) dhe 299 terma leksiku. Offline, me motor lokal për shumë variante.","tags":["shah"]},"Dame-fara-frontiere":{"line":"Luani 25 variante dame kundër kompjuterit dhe ruani lojën. Rregullat e 16 prej tyre janë vetëm të përafërta dhe shënohen me ⚠.","detail":"25 variante të damës të luajtshme kundër një AI didaktike, me eksport loje; 16 kanë rregulla të përafërta (shënuar ⚠).","tags":["damë"]},"Table-fara-frontiere":{"line":"Tavëll, tavli, nardi dhe variante rumune të tablës; lexoni dhe luani: 17 variante kundër kompjuterit, me tastierë ose mi.","detail":"Atlas i luajtshëm i familjes së tavllës: backgammon, Tavli, Tavla, Narde, Gul Bara dhe variante rumune; 17 variante kundër një AI mësimore; lojë me tastierë.","tags":["tavëll"]},"Remi-fara-frontiere":{"line":"Njihuni me familjen e ramit dhe luani 19 variante kundër kompjuterit me statistika. 8 gjuhë; pllaka ose letra të mëdha, lehtësisht të dukshme.","detail":"Atlas i familjes së lojërave rummy: 19 variante të luajtshme kundër një AI lokale, me statistika; ndërfaqe në 8 gjuhë, me pllaka dhe letra të mëdha.","tags":["rami"]},"Carti-de-joc-fara-frontiere":{"line":"Nga pasjansa dhe Pjetri i Zi te pokeri: 17 lojëra me letra me rregulla të shpjeguara, 8 prej të cilave mund t'i luani menjëherë.","detail":"Atlas interaktiv i lojërave me letra, nga Solitaire dhe Old Maid te pokeri: 17 lojëra me fletë rregullash, 8 prej tyre të luajtshme.","tags":["letra"]},"Undava":{"line":"Përgatitni një kuiz ose luajeni me miqtë në të njëjtin telefon ose kompjuter dhe rilozni pyetjet që i keni gabuar. I ngjashëm me Kahoot, por pa lidhje.","detail":"Kuiz në stilin Kahoot (i palidhur me të), në një skedar të vetëm: vetëm ose me radhë në të njëjtën pajisje, me rishikim të gabimeve. Loja e drejtpërdrejtë është vetëm në edicionin me server.","tags":["kuiz","edukim"]},"AI-Liber":{"line":"Bisedoni me disa asistentë të inteligjencës artificiale në një vend, disa funksionojnë në kompjuterin tuaj. Mesazhet shkojnë te ofruesi që zgjidhni; IA mund të gabojë.","detail":"Bisedë me shumë ofrues AI, përfshirë ata lokalë (Ollama, WebLLM). Mesazhet shkojnë te ofruesi që zgjidhni; përgjigjet e AI mund të jenë të gabuara.","tags":["IA"]},"LocalMind":{"line":"Bisedoni me një asistent të vogël të inteligjencës artificiale që funksionon drejtpërdrejt në shfletuesin tuaj. Modelet shkarkohen nga interneti një herë; mund të gabojë.","detail":"Bisedë me modele të vogla (Qwen3, LFM2) të ekzekutuara lokalisht në shfletues (WebGPU). Modelet vijnë nga Hugging Face; mund të gabojë. Kërkon një server lokal ose faqen publike.","tags":["IA lokale"]},"PromptVault":{"line":"Mbi 500 kërkesa të gatshme për asistentët e inteligjencës artificiale; zgjidhni dhe shënoni të preferuarat. Nuk i ruan tekstet tuaja.","detail":"Bibliotekë me mbi 500 prompte me të preferuara, jo menaxher për promptet tuaja.","tags":["kërkesa"]},"ARENA":{"line":"I bëni dy modele IA të përgjigjen verbërisht dhe votoni për më të mirin; renditja ruhet në kompjuterin tuaj. Nevojiten çelësat tuaj.","detail":"Dyluftime të verbra midis modeleve AI me renditje Elo lokale (eksport CSV). Kërkon çelësat tuaj API ose serverë lokalë; modelet demonstruese janë të simuluara.","tags":["vlerësim IA"]},"Nexus-fara-frontiere":{"line":"Bisedoni me asistentë IA nga disa ofrues; bisedë me kërkim dhe ruajtje. Nevojiten interneti dhe çelësat tuaj, që ruhen të pashifruar.","detail":"Klient bisede AI me çelësat tuaj API (Anthropic, OpenAI, Google, të përputhshëm me OpenAI), me kërkim dhe eksport Markdown; “agjentët” janë prompte. Kërkon internet; çelësat ruhen pa enkriptim.","tags":["agjentë"]},"VoiceAtelier":{"line":"Dëgjoni si tingëllojnë qindra zëra artificialë në dhjetëra gjuhë dhe mësoni si bëhet një audiolibër. Shembulli online e dërgon tekstin te shërbime të jashtme vetëm me lejen tuaj.","detail":"Katalog me 427 zëra neuralë (141 gjuhë/vende) dhe udhëzues audiolibrash. Mostra online e dërgon tekstin te një ndërmjetës dhe te Microsoft, vetëm me pëlqimin tuaj. Nuk është studio TTS.","tags":["zë"]},"Trusa-fara-frontiere":{"line":"Një set me 15 mjete të vogla të përditshme: shënime, tabelë, Markdown, fjalëkalime, ditar financiar e të tjera. Nuk ka lidhje zyrtare me YunoHost që frymëzoi kategoritë.","detail":"Një set me 15 module të vogla të shkruara nga zero (shënime, fletë llogaritjeje, Markdown, fjalëkalime, ditar financash e të tjera), të frymëzuara nga kategoritë e aplikacioneve YunoHost; të palidhura me to.","tags":["mjete"]},"API-fara-frontiere":{"line":"Moti, imazhet e NASA-s, pozicioni i ISS-së dhe dhjetëra të dhëna drejtpërdrejt në një vend. Kërkon internet; nuk është provuar me shërbime reale.","detail":"52 miniaplikacione: 47 mbi API publike (kërkon internet; kur hapet online kontakton automatikisht Open-Meteo, NASA dhe ISS) dhe 5 mjete lokale. Të patestuara kundër serverëve realë.","tags":["API"]},"OmniHost":{"line":"Një paketë e madhe me mbi njëqind mjete pune në një vend. Lidhet me katër shërbime të jashtme; detajet janë te README.","detail":"Suitë produktiviteti (~4 MB, 141 module). Kontakton katër host të jashtëm; shihni README.","tags":["paketë"]},"VNTV":{"line":"Luani trailerët e VideoNeat si një kanal televiziv pa ndërprerje. Kërkon internet; në mënyrën P2P adresa juaj është e dukshme për shikuesit e tjerë.","detail":"Pjesët promovuese të VideoNeat si program i vazhdueshëm televiziv, plus një shtesë Stremio. Kërkon internet (videoneat.com, videos.trom.tf); në mënyrën P2P, IP-ja juaj është e dukshme për shikuesit e tjerë.","tags":["media","MIT"]},"OSATURA":{"line":"Jepini jetë vizatimeve 2D: lidhini me një «skelet», vëreni në lëvizje dhe eksportoni animacionin në disa formate. Version alfa, deri tani pak i provuar.","detail":"Motor rigging dhe animacioni vektorial 2D në Rust (kocka, IK, skinning, fizikë, makina gjendjesh) me studio në shfletues dhe eksport në SVG, PNG, GIF, Lottie dhe glTF. Program vendas (linjë komande + studio) dhe modul WebAssembly, jo një skedar i vetëm HTML; alfa, ende pak i provuar nga përdoruesit. Licenca: biblioteka MPL-2.0, CLI AGPL-3.0-or-later.","tags":["animacion","MPL/AGPL"]},"OAZA":{"line":"340 shërbime web falas, kryesisht pa llogari, në një katalog. Lista u kontrollua në qershor 2026, por jo automatikisht.","detail":"Katalog me 340 shërbime ueb falas të palëve të treta, zakonisht të përdorshme pa llogari (të paverifikuara automatikisht; kontrolluar në qershor 2026).","tags":["shërbime"]},"VaultCrypt":{"line":"Keni diçka për të fshehur nga sytë kureshtarë? Kyçni skedarë dhe tekste me fjalëkalim drejtpërdrejt në shfletues. Një fjalëkalim i humbur nuk rikthehet.","detail":"Enkriptim AES-256-GCM i skedarëve dhe tekstit në shfletues. I pa audituar në mënyrë të pavarur; një fjalëkalim i humbur nuk mund të rikuperohet.","tags":["siguri"]},"Akasha":{"line":"Fletore që funksionon jashtë linje, me etiketa, kërkim dhe lidhje mes faqeve. Që të mos humbisni asgjë, shkarkoni një kopje të freskët të skedarit.","detail":"Shënime offline në një skedar të vetëm, me etiketa, kërkim dhe lidhje [[Titulli]]; për të ruajtur të dhënat shkarkoni një kopje të re të skedarit (quine).","tags":["shënime"]},"CLEPSIDRA":{"line":"Ora e numërimit mbrapsht, alarm dhe orare për ditët e punës dhe fundjavat. Ndjek festat dhe ngjarjet tuaja.","detail":"Orë e kundërt, alarm, orare për ditët e punës/fundjavën, festa, ngjarje.","tags":["koha"]},"Origami":{"line":"Mësoni të paloseni letrën hap pas hapi: simbole, teknika dhe modele të ilustruara. Aplikacioni kujton ku ishit ndalur.","detail":"Udhëzues origami: shënime, teknika, modele hap pas hapi, me progres të ruajtur lokalisht.","tags":["art"]},"Zicala":{"line":"Çdo ditë një proverb rumun nga një koleksion prej 550. Mund të kërkoni dhe të ruani të preferuarat; komentet u shkruan me ndihmën e IA-së.","detail":"550 proverba rumune me proverbin e ditës, kërkim dhe eksport/import të të preferuarave; komentet SWOT/TOWS janë të asistuara nga AI.","tags":["kulturë"]},"Limpezimea":{"line":"Lexoni romanin shkencor-fantastik «Limpezimea» në shtatë gjuhë. Kronika shoqëruese dhe studimi kritik u shkruan me ndihmën e IA-së (Claude).","detail":"Romani shkencëfantastik “Limpezimea” në 7 gjuhë, edicion leximi. Aparati kritik (kronika, studimi) është shkruar me ndihmën e AI (Claude).","tags":["letërsi"]},"Nota-Zero":{"line":"Një tregim fantastik spekulativ mbi teorinë e telave në rumanisht, anglisht dhe frëngjisht, me shënime që shpjegojnë idetë shkencore. Është fiksion, jo burim akademik.","detail":"Tregim fiksioni spekulativ për teorinë e vargjeve, në rumanisht, anglisht dhe frëngjisht, me shënime shkencore shpjeguese (fiksion, jo burim akademik).","tags":["letërsi"]},"Pendulul":{"line":"Një planet lëkundet mes tre yjesh dhe një vrime të zezë: roman shkencor-fantastik me nëntë vëllime që Alexio e shkroi së bashku me Claude. Simulim 3D, lexues me ruajtje për lexim jashtë linje, EPUB dhe PDF.","detail":"Roman shkencëfantastik me nëntë vëllime nga Alexio, shkruar me Claude: një planet lëkundet midis tre yjeve dhe një vrime të zezë. Përfshin një simulim 3D dhe lexuesin e librit në një skedar të vetëm HTML që mund ta ruani dhe lexoni offline, plus EPUB dhe PDF.","tags":["letërsi"]},"PrintreInteligente":{"line":"Hyni në një roman interaktiv shkencor-fantastik me personazhe të frymëzuar nga ekuipazhi i Artemis 2. Shqyrtimet janë të trilluara; përkthimi, zëri dhe funksionet e IA-së përdorin shërbime të jashtme.","detail":"Roman interaktiv shkencëfantastik, fiksion me personazhe të frymëzuar nga ekuipazhi i Artemis 2; recensionet janë fiktive. Përkthimi, zëri online dhe funksionet AI përdorin shërbime të jashtme.","tags":["letërsi"]},"BorderlessMelodies":{"line":"Dëgjoni muzikë që e kompozon vetë veten drejtpërdrejt në shfletues. Mund ta eksportoni si audio; ka kohëmatës gjumi.","detail":"Muzikë procedurale në Web Audio, me eksport audio dhe kohëmatës gjumi.","tags":["muzikë"]},"EcoulSpectral":{"line":"Shikojeni zërin si imazh, zgjidhni pjesën që ju shqetëson dhe ndajeni ose fshijeni. Përfshin zvogëlim zhurme, zbulim tingujsh dhe ruajtje si WAV.","detail":"Redaktor lokal spektrogrami: shënoni një zonë kohë–frekuencë dhe izolojeni ose hiqeni; zbulim zëri, reduktim zhurme, eksport WAV.","tags":["audio"]},"Constelar":{"line":"Bisedoni me miq virtualë që i kujtojnë bisedat tuaja. Si parazgjedhje përgjigjen sipas rregullave të thjeshta; IA e vërtetë vetëm nëse zgjidhni një ofrues, dhe atëherë mesazhet tuaja shkojnë tek ai. Vetëm për të rritur.","detail":"Shokë bisede me kujtesë lokale. Si parazgjedhje një motor i thjeshtë me rregulla; AI e vërtetë vetëm nëse zgjidhni një ofrues (mesazhet i dërgohen atij). Për të rritur; nuk zëvendëson terapinë.","tags":["IA"]},"Tarot":{"line":"Zbuloni historinë e tarotit, simbolet e letrave dhe mënyrën si lexohen si fenomen kulturor. Kurs interaktiv me ritmin tuaj.","detail":"Kurs interaktiv: historia, simbolet dhe leximi i letrave, si fenomen kulturor.","tags":["kulturë"]},"Numerologie":{"line":"Zbuloni numerologjinë si traditë simbolike në katër nivele, me ushtrime, fjalor, ditar dhe llogaritës. Paraqitet pa vërtetim shkencor.","detail":"Kurs interaktiv për numerologjinë si traditë simbolike: katër nivele, ushtrime, fjalor, ditar dhe kalkulator; paraqitur pa vlerësim shkencor.","tags":["kulturë"]},"PUNCTUM":{"line":"Atlas edukativ i akupresurës dhe terapive me pika: mbi 400 pika në harta interaktive, rutina vetëkujdesi me seanca të udhëhequra, prova dhe siguri. Nuk e zëvendëson mjekun.","detail":"Atlas edukativ i terapive me pika (akupunkturë, akupresurë, moksibustion, kupa vakumi, terapi aurikulare, refleksologji e të tjera): 410 pika në 14 meridianë, 60 variante me nivel dëshmish, harta SVG, gjendje dhe rutina, një kurs, kuiz, kartela dhe kontrolle personale sigurie.","tags":["shëndet","prova"]},"Reiki":{"line":"Mësoni çfarë është reiki, një praktikë shpirtërore, dhe çfarë thonë hulumtimet: nuk u gjetën prova të mjaftueshme për efekt përtej çlodhjes. Nuk e zëvendëson mjekun.","detail":"Kurs për Reiki-n, një praktikë shpirtërore: rishikimet nuk gjejnë dëshmi të mjaftueshme për ndonjë efekt përtej relaksimit/placebos; nuk zëvendëson mjekun.","tags":["kulturë"]},"Bioenergoterapie":{"line":"Kurs që shpjegon çfarë është bioenergjetika terapeutike dhe nga vjen. Nuk ka prova shkencore për efekt shërues të praktikës; nuk e zëvendëson mjekun.","detail":"Kurs për terapinë bioenergjetike, një praktikë pa dëshmi shkencore shërimi; nuk zëvendëson mjekun.","tags":["kulturë"]},"CHIROMANTIA":{"line":"Atlas interaktiv i kiromancisë: hartë e pëllëmbës me vija, kodra, gishta dhe lloje duarsh, e lexuar si traditë kulturore; me një seksion mbi shkencën dhe të menduarit kritik. Pa vërtetim shkencor.","detail":"Atlas interaktiv i kiromancisë: hartë SVG e pëllëmbës (e majtë/e djathtë), vija, kodra, gishta, tipa duarsh, gjurmë gishtash, matje 2D:4D, lexim i udhëhequr, kartela, kuiz, test i verbër Barnum dhe simulator i leximit të ftohtë; çdo pretendim ka nivel dëshmish.","tags":["kiromanci","kulturë"]},"Radiestezie":{"line":"Kaloni 18 nivele mbi kërkimin e ujit me shufër, me fjalor, ditar praktike dhe shtojca ndërkombëtare. Që në fillim thotë se nuk ka vërtetim shkencor.","detail":"Kurs me 18 nivele për radiestezinë, me fjalor, ditar praktike dhe shtojca ndërkombëtare; thotë që në fillim se nuk ka vlerësim shkencor.","tags":["kulturë"]},"Inforenergetica":{"line":"Mësoni në një kurs të strukturuar çfarë pretendon inforenergjetika, një praktikë jo konvencionale. Pa vërtetim shkencor; nuk është këshillë mjekësore.","detail":"Kurs për inforenergjetikën, një praktikë jokonvencionale pa vlerësim shkencor; nuk është këshillë mjekësore.","tags":["kulturë"]},"ECLIPSA":{"line":"Mësoni në cilën shtëpi astrologjike të hartës suaj natale bie një eklips dhe për 12 eklipset e ardhshme. Llogaritja është e përafërt, interpretimi simbolik; pa vërtetim shkencor.","detail":"Në cilën shtëpi astrologjike bie një eklips në një hartë natale, plus 12 eklipset e ardhshme. Llogaritje astronomike lokale, e përafërt; interpretim simbolik, astrologjia nuk ka vlerësim shkencor.","tags":["astrologji"]},"Afrodisiace-fara-frontiere":{"line":"Lexoni për 22 ushqime dhe bimë që lidhen tradicionalisht me dëshirën, me nivelin e provave për secilën. Udhëzues kulturor për të rritur, jo këshillë mjekësore.","detail":"Udhëzues kulturor për 22 ushqime dhe bimë të lidhura tradicionalisht me dëshirën, me nivel dëshmish për çdo hyrje. Edukativ, jo këshillë mjekësore.","tags":["kulturë"]},"CalmWaves":{"line":"Muzikë ambientale për çlodhje dhe gjumë, e krijuar menjëherë. Nuk është pajisje mjekësore; seksioni mbi kërkimin nuk është verifikuar në mënyrë të pavarur. Konsultohuni me mjekun (epilepsi).","detail":"Muzikë ambientale gjeneruese për relaksim/gjumë. Nuk është pajisje mjekësore; seksioni i kërkimit nuk është verifikuar në mënyrë të pavarur. Kërkoni këshillë mjekësore (epilepsi).","tags":["audio"]},"ASMR":{"line":"Krijoni peizazhin tuaj qetësues tingullor nga shtresa mjedisi, tinguj prekjeje dhe rrahje binaurale. Ka kohëmatës gjumi dhe mund ta ndani miksin tuaj.","detail":"Mikser tingujsh relaksues i gjeneruar në kohë reale (Web Audio): shtresa ambientale, tinguj prekjeje, ritme binaurale dhe kohëmatës gjumi; miks i ndashëm.","tags":["audio"]},"NOMIA":{"line":"Si mund të ishte kontakti i parë mes njerëzve, IA-ve dhe llojeve të tjera mendjesh? 1001 skenarë imagjinarë; fiksion, jo realitet. Funksionon edhe jashtë linje.","detail":"Simulator konceptual i protokolleve të kontaktit Njeri–AI–NHI, 1001 hyrje, shoqërues i antologjisë “Printre inteligențe”. Fiksion/spekulim, jo fakte të verifikuara; PWA offline, RO/EN.","tags":["fiksion","spekulim","PWA"]},"ValeaPlopului1972":{"line":"Shikoni një ngjarje UFO të vitit 1972 nga jashtë, nga brenda dhe në simulim, të rindërtuar në 3D. Është një hipotezë imagjinare, jo provë.","detail":"Rindërtim 3D i rastit UAP Valea Plopului (1972): pamja e jashtme, simulim, brendësi e imagjinuar. Spekulativ, bazuar në burime publike të paverifikuara, pa pëlqimin e personave të emërtuar; nuk është dëshmi.","tags":["UFO","3D","fiksion"]},"HoroScop":{"line":"Llogaritni pozicionet e planetëve për një datë dhe vend, pastaj eksploroni hartën natale, aspektet dhe përputhshmërinë. Astrologji simbolike, pa bazë shkencore. Funksionon jashtë linje.","detail":"Efemeridë personale offline: pozicione planetare të llogaritura në shfletues (saktësi e reduktuar), hartë natale, aspekte, sinastri. Astrologji simbolike, pa vlerësim shkencor; licencë MIT.","tags":["astrologji","efemeride","jashtë linje"]},"Aurora":{"line":"Dëgjoni tone qetësuese dhe tinguj që pulsojnë lehtë dhe ndiqni një udhëzues frymëmarrjeje. Vetëm për çlodhje, nuk është trajtim. Funksionon pa internet.","detail":"Strehë tingujsh: tone çakrash, ritme binaurale dhe udhëzues frymëmarrjeje, offline. Vetëm për relaksim, jo mjekësi; frekuencat nuk kanë vlerësim shkencor. Licencë MIT; projekt i pavarur.","tags":["meditim","audio","çlodhje"]},"NumeroLogIA":{"line":"Mësoni çfarë thonë numerologjia, astrologjia kineze BaZi dhe bioritmi për datën tuaj të lindjes, me çdo llogaritje të shpjeguar. Sistem simbolik, pa bazë shkencore.","detail":"Numerologji pitagoriane/kaldease, BaZi dhe biorritëm në 7 gjuhë, llogaritje hap pas hapi, portrete të eksportueshme si JSON; orakull AI opsional përmes modelit tuaj. Sistem simbolik, pa vlerësim shkencor; licencë MIT.","tags":["numerologji","IA","jashtë linje"]},"FrequencyLaboratory":{"line":"Provoni tinguj, efekte dhe teste dëgjimi në një laborator të vogël zëri. Efektet «terapeutike» nuk janë provuar; nuk e zëvendëson mjekun. Funksionon jashtë linje.","detail":"Laborator audio në shfletues (oshilatorë, binaural, efekte, analizues, teste dëgjimi), offline. Vetëm për informim: paracaktimet “terapeutike” nuk kanë efekt mjekësor të provuar; nuk është pajisje mjekësore.","tags":["audio","laborator","jashtë linje"]},"generator-frecvente":{"line":"Krijoni tone të pastra dhe çifte që pulsojnë, dëgjoni paracaktime të njohura dhe kontrolloni përafërsisht dëgjimin tuaj. Nuk është pajisje mjekësore. Funksionon jashtë linje.","detail":"Gjenerator tonesh në shfletues (binaural, sekuencues, EQ, test dëgjimi orientues, kërkim paracaktimesh), offline. Vetëm për informim: paracaktimet Solfeggio/Schumann nuk kanë vlerësim shkencor; nuk është pajisje mjekësore.","tags":["audio","gjenerues","jashtë linje"]},"ACORDAJ":{"line":"Shfletoni mbi një mijë kurse shpirtërore dhe inicime me kontekst historik dhe vështrim kritik. Nuk është i lidhur me faqen burimore dhe nuk ka vërtetim shkencor. Funksionon jashtë linje.","detail":"Atlas offline i 1134 kurseve/iniciimeve shpirtërore (lista nga cursurispirituale.webnode.ro, e palidhur me të), me kontekst historik dhe gjykim kritik; pa vlerësim shkencor.","tags":["shpirtërore","atlas","dallim kritik"]},"Profund":{"line":"150 pyetje që e çojnë bisedën përtej llafeve të zakonshme — mes miqve ose në familje. Luani në ekran ose printoni, me kohëmatës opsional.","detail":"Lojë me 150 pyetje për biseda me kuptim (RO/EN/FR), online ose e printuar, me lojtarë dhe kohëmatës opsional; përshtatur nga deepcards.org, origjinalet mbeten pronë e mbajtësve të të drejtave (MIT vetëm për kodin dhe pjesën origjinale).","tags":["bisedë","karta","trade-free"]},"Universul-Observabil":{"line":"Sa i madh është Universi i dukshëm? Krahasoni tri harta (lineare, të sheshtë, në hapësirë) dhe bëni llogaritje kozmologjike. Numrat nuk janë verifikuar në mënyrë të pavarur.","detail":"Faqe qendrore që paraqet dhe krahason vizualizimet 1D, 2D dhe 3D të Universit të vëzhgueshëm, me kalkulator kozmologjik offline; shifrat dhe rekordet janë nga katalogu i majit 2026, të paverifikuara në mënyrë të pavarur. RO/EN.","tags":["astronomi","kozmologji","vizualizim"]},"Universul-Observabil-1D":{"line":"Udhëtoni nga ne deri në skajin e Universit të dukshëm duke kaluar 112 galaktika të vendosura në një bosht. Ton ironik, vlera të rrumbullakosura, qëllim edukativ.","detail":"Hartë 1D e Universit të vëzhgueshëm: 112 galaktika në një bosht radial (kohë, distancë, zhvendosje drejt të kuqes), me tabelë të dhënash dhe eksport CSV. Edukativ, me ton ironik; vlera të rrumbullakosura, rekorde që nga data e katalogut (maj 2026).","tags":["astronomi","kozmologji","vizualizim"]},"Universul-Observabil-2D":{"line":"Hartë galaktikash në botimin satirik «Toka e Sheshtë»: është një shaka, Toka nuk është e sheshtë. Zmadhoni mes 111 galaktikave; distancat janë të përafërta. Funksionon jashtë linje.","detail":"Hartë interaktive 2D e universit të vëzhgueshëm (111 galaktika, shkallë logaritmike, të dhëna JWST) në një edicion satirik “Toka e sheshtë”: parodi, Toka nuk është e sheshtë; distancat janë të përafërta. RO/EN, offline.","tags":["astronomi","satirë","kozmologji"]},"Universul-Observabil-3D":{"line":"Fluturoni mes mbi 115 galaktikave në një hartë 3D me turne të udhëhequra dhe misione. Vlerat janë të përafërta.","detail":"Hartë interaktive 3D (WebGL) e universit të vëzhgueshëm: 115+ galaktika, 12 horizonte, 30 turne, sfida në udhëzues, eksport GLB/CSV/BibTeX. Vlera të përafërta; rekordet JWST që nga maji 2026.","tags":["astronomi","kozmologji","3D"]},"QSO":{"line":"Mbani ditarin e lidhjeve radio të stacionit tuaj radioamator me orën UTC, lokatorë dhe statistika. Jozyrtar; llogaritjet janë të përafërta.","detail":"Ditar jozyrtar stacioni radioamator: QSO me orë UTC, import/eksport ADIF 3.1, lokatorë Maidenhead, kontrolle dublikatash, statistika. Tabelë e pjesshme prefiksesh (jo DXCC); llogaritje të përafërta.","tags":["radio","ditar"]},"Curatitor":{"line":"Shikoni çfarë zbulojnë fotot dhe skedarët tuaj (vendi, kamera, autori) dhe hiqini këto të dhëna para dërgimit. Nuk i fsheh fytyrat apo përmbajtje tjetër të dukshme.","detail":"Shfaq dhe heq metadatat e skedarëve lokalisht (GPS, kamera, autori, softueri) pa rikodimin e pikselëve ose audios, dhe e kontrollon sërish rezultatin. Nuk anonimizon përmbajtjen (fytyra, zhurma e sensorit).","tags":["metadata","privatësi"]},"Poteca":{"line":"Hapni gjurmë të regjistruara në ecje ose me biçikletë dhe shihni distancën, ngjitjen dhe profilin e lartësisë. Mund t'i prisni ose bashkoni. Pa hartë; ngjitja është e vlerësuar.","detail":"Shikues dhe redaktor për gjurmë GPX/GeoJSON/KML/CSV: statistika, profil lartësie, prerje, bashkim, thjeshtim, eksport. Pa hartë bazë; ngjitja/zbritja janë vlerësime.","tags":["GPX","gjurmë"]},"Orar":{"line":"Kalendar dhe planifikues javor me festat zyrtare rumune, me pamje ditore, javore ose mujore. Alarmet bien vetëm për sa kohë faqja mbetet e hapur.","detail":"Kalendar dhe planifikues javor: pamje muaji/jave/dite/axhende, përsëritje RFC 5545, zona orare, festa publike rumune, import/eksport .ics. Alarmet bien vetëm kur skeda është e hapur.","tags":["kalendar","koha"]},"Alfabete":{"line":"Mësoni dhe stërviteni me alfabetin Morse, Brailën, alfabetin fonetik, semaforin me flamuj dhe shifra të vjetra, pastaj printoni një faqe. Shifrat e vjetra nuk i mbrojnë sekretet.","detail":"Referencë, konvertues, trajner dhe fletë e printueshme për Morse, braj (shkalla 1), alfabete fonetike, semafor, Baudot, baza numrash dhe shifra klasike. Shifrat klasike nuk ofrojnë siguri.","tags":["kode","mësim"]},"Fabrica":{"line":"Shkruani një kurs si tekst të thjeshtë dhe kthejeni në një faqe me mësime, test përfundimtar dhe certifikatë për printim. Certifikata nuk ka vlerë zyrtare.","detail":"Fabrikë kursesh dhe kuizesh: shkruani një kurs në Markdown të thjeshtë dhe eksportojeni si një skedar HTML të vetëm e të vetëmjaftueshëm me progres lokal, test përfundimtar dhe certifikatë të printueshme (pa vlerë akreditimi).","tags":["kurse","krijim"]},"Bolta":{"line":"Si ishte qielli mbi kokë në çdo vend dhe ditë midis 1900 dhe 2100? Dielli, Hëna, planetët dhe yjet, si dhe eklipsi i 2027. Vlerat janë të llogaritura, jozyrtare. Funksionon jashtë linje.","detail":"Planetarium offline për çdo vend dhe kohë midis 1900 dhe 2100: Dielli, Hëna, planetët, 1,627 yje, yjësi, ngjarje dhe një faqe për eklipsin e 2027. Vlera të llogaritura, jozyrtare.","tags":["astronomi","planetar"]},"BRAZDA":{"line":"Dekodoni Diskun e Artë të Voyager hap pas hapi, pastaj kodoni një disk të ri për një sondë që lëshohet tani. Imazhet në hapat e parë janë skematike, jo të NASA-s.","detail":"Dekodues dhe kodues me 12 hapa për Voyager Golden Record: shpejtësia, ora e hidrogjenit, harta e pulsarëve, sinjali i një imazhi, kalibrimi me rrethin, dekodim rresht pas rreshti, ngjyra, skedari juaj, kontributet dhe kodimi i një disku 2026–2027.","tags":["Voyager","sinjal"]},"Arbore":{"line":"Ndërtoni pemën e familjes me persona, familje, vijë kohore dhe një llogaritës rumun të farefisnisë. Të dhënat mbeten vetëm në këtë shfletues, pa sinkronizim.","detail":"Gjenealogji lokale: persona, familje, import/eksport GEDCOM 5.5.1, grafikë SVG, kronologji, kalkulator farefisnie (vetëm terminologji rumune). Pa sinkronizim; të dhënat mbeten në këtë shfletues.","tags":["gjenealogji","GEDCOM"]},"Gospodar":{"line":"Ndiqni paratë e shtëpisë: llogari, shpenzime, buxhete mujore dhe raporte. Nuk nevojitet llogari, por nëse humbisni fjalëkalimin, humbisni të dhënat. Nuk është këshillë financiare.","detail":"Buxhet lokal i shtëpisë: llogari, kategori, transaksione, import CSV, buxhete mujore, raporte dhe kalkulatorë me formula transparente. Pa llogari apo sinkronizim; një fjalëkalim i humbur do të thotë të dhëna të humbura. Nuk është këshillë financiare.","tags":["buxhet","financa personale"]},"Decibel":{"line":"Matni sa e fortë është zhurma përreth jush dhe shihni nga cilët tinguj përbëhet. Ka edhe një test orientues dëgjimi. Nuk është pajisje e certifikuar; rezultatet varen nga mikrofoni.","detail":"Matës niveli zëri, analizues spektri (1/3 oktavë, FFT) dhe test dëgjimi orientues. Nuk është matës i çertifikuar dhe nuk ka vlerë ligjore ose mjekësore; leximet varen nga mikrofoni dhe kalibrimi.","tags":["zë","matje"]},"Provenienta":{"line":"Keni një imazh dhe dëshironi të dini kush e ka nënshkruar dhe çfarë redaktimesh ka deklaruar? Kontrolloni nënshkrimin dixhital të ngulitur. Eksperimentale, e provuar vetëm në skedarë shembull.","detail":"Kontrollues lokal, eksperimental i C2PA / Content Credentials: tregon kush ka nënshkruar dhe cilat redaktime janë deklaruar, dhe verifikon nënshkrimin dhe lidhjen me bajtet e skedarit. Testuar vetëm me skedarë sintetikë; pa listë besimi.","tags":["C2PA","origjina"]},"Lexicon":{"line":"Sillni fjalorët tuaj dhe kërkoni fjalë edhe nëse shkruani pa shenja diakritike ose me gabime. Vjen vetëm me një set të vogël demonstrimi. Funksionon jashtë linje.","detail":"Motor fjalori offline: sillni fjalorët tuaj (TSV/CSV, JSON, StarDict, dictd, XDXF) dhe kërkoni sipas prefiksit, pa ndjeshmëri ndaj theksit, të përafërt ose me tekst të plotë. Seti i përfshirë (345 hyrje) është demonstrim, jo fjalor i plotë.","tags":["fjalor","gjuhë"]},"VERIGA":{"line":"Gjen lidhje të prishura dhe skedarë jetimë në një faqe web ose dosje. Funksionon në Windows, macOS dhe Linux; kërkon pak njohje me kompjuterin.","detail":"Kontrollues lidhjesh (clean-room) për faqe ueb dhe dosje lokale, i shkruar në Rust: linjë komande, aplikacion desktop vendas (egui) dhe version HTML në një skedar të vetëm. Kontrollon lidhjet HTML dhe CSS, ridrejtimet, spiancat #fragment, skedarët jetimë, robots.txt dhe sitemap. Windows, macOS dhe Linux; licencë MIT.","tags":["kontroll lidhjesh","MIT"]},"TEZAUR":{"line":"Asistent teze që shkruan vetëm mbi bazën e librave dhe artikujve tuaj, me citime të verifikueshme. Funksionon në kompjuterin tuaj; dokumentet tuaja nuk e lënë kurrë. Në zhvillim.","detail":"Asistent kërkimi lokal për shkrimin e një teze, i shkruar në Rust, me përgjigje të bazuara në citime: indekson librat dhe artikujt tuaj (PDF, EPUB, DOCX, txt), nxjerr pasazhe dhe shkruan vetëm prej tyre, me citime [n] të kontrolluara dhe listë referencash. Punon në kompjuterin tuaj me një model lokal (Ollama, Jan, LM Studio); dokumentet tuaja nuk dalin kurrë prej tij. Version 0.x; licencë MIT.","tags":["kërkim","MIT"]},"LegatorOCR":{"line":"Skanoni një libër dhe merrni një PDF të pastër me faqe të korrigjuara dhe tekst që kërkohet. Funksionon në Windows, macOS dhe Linux; skanimet tuaja mbeten te ju.","detail":"Pas-përpunues clean-room i shkruar në Rust për libra të skanuar: ndan faqet e dyfishta, drejton pjerrësinë, pret, vendos margjinat, pastron dhe binarizon, pastaj eksporton një PDF ose imazhe me shtresë teksti OCR të kërkueshme. Aplikacion grafik (Windows, macOS, Linux) dhe linjë komande, në 8 gjuhë. Njohja e tekstit (OCR) kërkon programin e veçantë Tesseract; gjithçka tjetër punon pa të. Version 0.x; licencë MIT.","tags":["skanim","MIT"]},"Fenarium":{"line":"Atlas dhe punishte e perceptimeve subjektive nëpër të gjitha shqisat, duke filluar nga fosfenizmi: kurs me 13 module, eksperimente të udhëhequra, simulator vizual dhe laborator vetë-eksperimentesh A/B me randomizim. Edukativ, nuk është pajisje mjekësore.","detail":"Atlas i feneve (fosfene, pasimazhe, tinguj të ngjashëm me tinitusin e të tjera), kurs me 13 module, laborator vetë-eksperimentimi; nuk është pajisje mjekësore.","tags":["perceptim","MIT"]},"MENSURA":{"line":"Matni IQ, EQ, CQ, RQ, funksionet ekzekutive dhe shqisat në 6 fusha me 18 teste, indekse të përbërë dhe intervale besimi 95%. Norma të përkohshme, vetëm orientuese, nuk është diagnozë.","detail":"18 teste në 6 fusha (IQ, EQ, CQ, RQ, funksione ekzekutive, shqisa), indekse me intervale besimi, eksport/import JSON; norma të përkohshme.","tags":["teste","MIT"]},"Cronosala":{"line":"Kohëmatës për palestër: pushim midis serive, HIIT, Tabata, EMOM, AMRAP, qarqe dhe metronom, plus ditar stërvitjeje me kg dhe përsëritje.","detail":"Kohëmatës palestre dhe ditar stërvitjeje në një skedar të vetëm HTML: pushim adaptiv midis serive, Interval/HIIT, Tabata, EMOM, AMRAP, qarqe stacionesh, tempo, metronom, program mujor 4-javor, katalog ushtrimesh dhe kode QR për makineritë. Të dhënat mbeten në shfletues; ndërfaqja është në rumanisht.","tags":["sport","koha"]},"ScutSonor":{"line":"Zë i fortë dhe stroboskop i elektrikut të dorës për takime me qen agresivë, plus udhëzues sjelljeje. Është një ndihmë, jo një mburojë e garantuar.","detail":"Gjeneron një fshirje 2–8 kHz, ultratinguj eksperimentalë, një sirenë dhe test altoparlanti, me kufizues që ruan zhurmën, stroboskop me elektrik dore (2.5 Hz), mënyrë ditore dhe udhëzues sigurie. Skedar i vetëm, pa gjurmim. Dëshmitë se tingulli i largon qentë janë të dobëta.","tags":["siguri","zë"]},"MIRAJ":{"line":"Si sheh retina dhe si e ndërton truri imazhin: fovea, pika e verbër, iluzione dhe kuiz, në tri nivele.","detail":"Shpjegim interaktiv i shikimit në tri nivele (fillestar, i mesëm, i avancuar): retina, fovea, njolla e verbër, iluzione optike, një përmbledhje dhe kuiz me 10 pyetje. Skedar i vetëm, ndërfaqe në rumanisht dhe anglisht.","tags":["shikim","edukim"]},"ANTROPOS":{"line":"Profil shkencor orientues i llogaritur lokalisht: mosha biologjike PhenoAge, zëri, shkrimi i dorës, vizatimi i orës, personaliteti TIPI dhe koha e reagimit.","detail":"Mjet edukativ shqyrtimi, jo diagnozë: mosha biologjike PhenoAge me mbrojtje besueshmërie, analizë zëri, grafometri e shkrimit të dorës, teste ore dhe vizatimi i personit, TIPI, teste reagimi, raport i printueshëm dhe eksport JSON. Të dhënat mbeten në shfletues.","tags":["shqyrtim","biologji"]},"DESCANTAR":{"line":"Fall me 41 kokrra fasule (metoda 3×3, varianti i Oltenisë) dhe 12 magji tradicionale si objekt studimi folklorik.","detail":"Fall me fasule rumune në tri metoda (3×3 sipas librit, Oltenia, tri grumbuj), lexime sipas Kokës, Zemrës dhe Këmbëve, 12 magji tradicionale, faza e hënës, numërues recitimi, gjenerues magjish, histori dhe udhëzues i kopjueshëm. Përmbajtje folklorike e përkthyer në 8 gjuhë me AI, e pashqyrtuar nga folës vendas.","tags":["folklor","fasule"]},"Index-fara-frontiere":{"line":"Katalog i aplikacioneve HTML me një skedar: koleksioni chiuta.github.io dhe burime të jashtme, me kërkim dhe etiketa.","detail":"Tetë projekte nga koleksioni i autorit dhe tetë burime të jashtme, të shënuara qartë, me kërkim të drejtpërdrejtë, etiketa të klikueshme, ndërrues RO/EN, temë e errët/e çelët dhe një hyrje që katalogon veten. Pa kërkesa rrjeti. Një pamje statike e 5 korrikut 2026.","tags":["katalog","burime"]},"DECUPAJ":{"line":"Ktheni një podcast, audio ose video në klipe vertikale me titra drejtpërdrejt në shfletues, pa llogari dhe pa filigran. Skedarët tuaj nuk e lënë kurrë pajisjen.","detail":"Reels vertikale nga një podkast (audio ose video) në një skedar të vetëm HTML: zgjidhni segmentin në formën e valës, merrni sugjerime momentesh, transkriptim lokal me Whisper, nëntituj të stilizuar, 4 raporte pamjeje (9:16, 4:5, 1:1, 16:9), radhë eksporti dhe MP4 përmes WebCodecs. Ndërfaqe në 8 gjuhë.","tags":["reels","video"]},"LECTOR":{"line":"Libra të lexuar me zë drejtpërdrejt në shfletues: EPUB, DOCX, PDF, TXT ose tekst i ngjitur, pa llogari dhe pa server. Teksti nuk e lë kurrë pajisjen tuaj.","detail":"Dëgjoni libra të lexuar me zë nga një skedar i vetëm HTML: EPUB, DOCX, PDF (me OCR rumun për skanimet), TXT; zëra të pajisjes ose Piper ro_RO, fjala e folur e theksuar, kohëmatës gjumi, kapituj, faqeshënues, fjalor shqiptimi, bibliotekë lokale dhe tema miqësore për disleksinë. Ndërfaqe në 8 gjuhë.","tags":["audio","libra"]},"FARFURIA":{"line":"Dietolog dixhital falas: kalori dhe makro të personalizuara, plan vaktesh për 7 ditë, ditar ushqimi dhe ndjekje e peshës. Nuk e zëvendëson mjekun apo dietologun.","detail":"Një dietolog dixhital në një skedar të vetëm HTML: objektiva kalorish dhe makronutrientësh (Mifflin–St Jeor, niveli i aktivitetit, qëllimi), plan vaktesh 7-ditor me filtra dietash dhe alergjenësh, bazë të dhënash ushqimesh, ditar ushqimi dhe ndjekje peshe. Rregulla sigurie për të mitur, histori çrregullimesh të ngrënies dhe sëmundje të veshkave. Ndërfaqe në 8 gjuhë.","tags":["ushqim","shëndet"]},"VITALIS":{"line":"Shoqërues personal për shëndetin, jetëgjatësinë dhe biohakimin: nëntë shtylla të renditura sipas provave, llogaritës, pikë e stilit të jetesës dhe ritual ditor. Nuk është këshillë mjekësore.","detail":"Shoqërues shëndeti dhe jetëgjatësie në një skedar të vetëm HTML: nëntë shtylla të renditura sipas dëshmive, kalkulatorë (HOMA-IR, TyG, belli-ndaj-lartësisë, Mifflin–St Jeor, zona të rrahjeve të zemrës, cikle gjumi, proteina), kohëmatës agjërimi, ritmues frymëmarrjeje, rezultat 360 me grafik radar, intervale referimi të biomarkerëve dhe ndjekës i ritualit ditor. Shoqërues jozyrtar për ngjarjen BioHacking360. Ndërfaqe në 8 gjuhë.","tags":["shëndet","jetëgjatësi"]},"REZONANTA":{"line":"Udhëzues dhe mjete për komunikimin dhe median: mesazh, kanale, njoftim për shtyp, intervistë, qartësi, plan dhe krizë.","detail":"Si t’i bësh njerëzit të dëgjojnë, në një skedar të vetëm HTML: 12 parime me test praktik, “shtëpia e mesazhit” (një prezantim 30-sekondash, një postim, version i shkurtër dhe i folur), rekomandime kanalesh mediatike, gjenerues komunikatash për shtyp me piramidë të përmbysur, fletë intervistë, analizues qartësie teksti, plan komunikimi me eksport tekst/CSV dhe hapat e orës së parë të një krize. Ndërfaqe në 8 gjuhë.","tags":["komunikim","media"]},"Claritas":{"line":"Zgjerim gjithëpërfshirës i shfletuesit për aksesueshmëri: korrigjim kontrasti, mënyrë leximi, lexim me zë dhe kontroll WCAG. Pa telemetri, pa rrjet, pa llogari.","detail":"Shtesë falas aksesueshmërie për shfletuesin: korrigjim automatik kontrasti (WCAG AA/AAA), tema me kontrast të lartë, filtra për daltonizmin, tekst më i madh dhe shkronja miqësore për disleksinë, vizore leximi, maskë dhe lupë, mënyrë leximi, lexim me zë, objektiva klikimi të mëdhenj dhe skanim me një çelës, auditim WCAG 2.2, pamje ekrani lokale dhe regjistrim ekrani. Për Chromium, Firefox dhe Safari; ndërfaqe në 8 gjuhë.","tags":["aksesueshmëri","zgjerim"]},"TurboCursa":{"line":"Lojë arkade garash pseudo-3D e shkruar në Rust: peizazhe të gjeneruara nga një farë, 11 mënyra, karrierë në ligë dhe 2 lojtarë. Origjinale; pa kod apo burime nga një lojë tjetër.","detail":"Lojë garash arcade pseudo-3D clean-room e shkruar në Rust: motor, art, muzikë dhe emër origjinal, gjithçka e gjeneruar nga një farë (19 peizazhe), fushatë, provë kohe, pa fund, Rush Hour, slallom, pasqyrë, Blackout, Zen, kundër CPU-së, ekran i ndarë për dy lojtarë dhe karrierë me divizione. Punon vendas ose si skedar uebi; ndërfaqe në 8 gjuhë.","tags":["gara","Rust"]},"ANTENA":{"line":"Në zhvillim: zgjidhës antenash me tel i përputhshëm me NEC-2 (metoda e momenteve), me ndërfaqe në shfletues. Për momentin vetëm një skelet pre-alfa.","detail":"Punë në vazhdim: një zgjidhës antenash me tela, i përputhshëm me NEC-2 (metoda e momenteve), me ndërfaqe në shfletues. Për momentin vetëm një skelet pre-alfa.","tags":["radio","antena"]},"ARBITRU":{"line":"Në zhvillim: motor universal rregullash për lojëra me tabelë, letra, zare dhe enigma me gjuhë deklarative rregullash. Për momentin vetëm një skelet pre-alfa.","detail":"Punë në vazhdim: një motor rregullash universal për lojëra me tabelë, letra, zare dhe enigma, me gjuhë deklarative rregullash. Për momentin vetëm një skelet pre-alfa.","tags":["lojëra","rregulla"]},"ASTROLABIU":{"line":"Në zhvillim: motor ngjarjesh qiellore në Rust të pastër (shkallë kohore, eklipse, lindje dhe perëndime, kalendarë). Për momentin vetëm një skelet pre-alfa.","detail":"Punë në vazhdim: një motor ngjarjesh qiellore (shkallë kohe, eklipse, lindje dhe perëndim, kalendarë), në Rust të pastër. Për momentin vetëm një skelet pre-alfa.","tags":["astronomi","kalendarë"]},"ECOGRAMA":{"line":"Në zhvillim: redaktues spektrogramesh dhe restaurim zëri: zgjidhni në spektrogram, riparoni, eksportoni. Për momentin vetëm një skelet pre-alfa.","detail":"Punë në vazhdim: një redaktor spektrogrami dhe restaurim audio: zgjidhni në spektrogram, riparoni, eksportoni. Për momentin vetëm një skelet pre-alfa.","tags":["audio","restaurim"]},"ecou-spectral-rs":{"line":"Në zhvillim: redaktues spektrogramesh natyral në Rust me shtojca për zvogëlim zhurme dhe zbulim tingujsh. Ekzistojnë skeleti i kodit dhe formati i shtojcave, por ende jo funksione të gatshme.","detail":"Punë në vazhdim: një redaktor vendas spektrogrami në Rust me shtojca për reduktim zhurme dhe zbulim zëri. Ka një skelet kodi dhe një format shtojcash, por ende asnjë funksion të përfunduar.","tags":["audio","Rust"]},"MARTOR":{"line":"Në zhvillim: kapje ligjore e uebit në WARC/WACZ me hashe, nënshkrime dhe vula kohore të besueshme, e verifikueshme jashtë linje. Për momentin vetëm një skelet pre-alfa.","detail":"Punë në vazhdim: kapje forenzike e uebit në WARC/WACZ me hash, nënshkrime dhe vula kohore të besuara, e verifikueshme offline. Për momentin vetëm një skelet pre-alfa.","tags":["arkivim","prova"]},"NEAMURI":{"line":"Në zhvillim: motor farefisnie — nga një rrugë në pemën e familjes te termi i saktë i farefisnisë në shumë gjuhë. Për momentin vetëm një skelet pre-alfa.","detail":"Punë në vazhdim: një motor farefisnie, nga një shteg në pemën e familjes te termi i saktë i të afërmit në shumë gjuhë. Për momentin vetëm një skelet pre-alfa.","tags":["farefisni","gjenealogji"]},"TACTIL":{"line":"Në zhvillim: shtresë dalje me prekje: formate Braile (BRF, Unicode), ekrane, printerë me reliev dhe dridhje e ekranit me prekje. Për momentin vetëm një skelet pre-alfa.","detail":"Punë në vazhdim: një shtresë dalje prekëse: formate braji (BRF, Unicode), ekrane, printera në reliev dhe dridhje në ekranin prekës. Për momentin vetëm një skelet pre-alfa.","tags":["Brailë","aksesueshmëri"]},"atelier-verificare":{"line":"Verifikoni foto, video, lidhje dhe domene në shfletuesin tuaj, asgjë nuk ngarkohet: lloji i vërtetë i skedarit dhe SHA-256, EXIF/GPS, XMP/IPTC, Content Credentials (vetëm lexim), analizë e nivelit të gabimit. Nuk mund të provojë se një foto është e vërtetë. Alfa.","detail":"Një paketë verifikimi për gazetarë dhe lexues të kujdesshëm që punon lokalisht. Shtoni imazhe, video, lidhje, domene ose tekst dhe merrni gjetje me nivel shqetësimi për secilën: lloji real i skedarit, SHA-256, EXIF dhe pozicioni GPS, XMP dhe IPTC, gjurmë gjeneratorësh imazhesh AI, manifeste Content Credentials (C2PA; lexohen, jo validohen), analizë e nivelit të gabimit për JPEG, metadata videosh me kuadro kyç për kërkim të kundërt imazhesh dhe anatomia e lidhjes. Dy kontrolle opsionale në rrjet (përmbledhje DNS, Internet Archive) ekzekutohen vetëm pasi shënoni një kuti pëlqimi. Raporti (Markdown, JSON ose PDF) rendit kufizimet e metodës. Nuk mund të provojë se një foto është autentike: metadata që mungojnë thonë pak dhe metadata mund të falsifikohen. Alfa; nëntë nga njëmbëdhjetë kontrollet punojnë offline; skedarët mbeten në shfletues.","tags":["gazetari","verifikim","foto"]},"balanta":{"line":"Krahasoni modele IA verbërisht: ngjitni përgjigjet e dy deri në tetë modeleve për 92 kërkesa në rumanisht, anglisht dhe hungarisht, votoni A ose B dhe merrni një renditje me intervale. Alfa; funksionon jashtë linje.","detail":"Vlerësim i verbër krah për krah i modeleve AI në rumanisht. Ju ngjitni vetë përgjigjet e çdo modeli (asgjë nuk thirret: pa çelësa API, pa llogari), aplikacioni fsheh emrat e modeleve brenda përgjigjeve, fikson renditjen nga një farë dhe regjistron votën tuaj. Renditja përdor Bradley–Terry dhe Elo me intervale bootstrap 95%, plus përqindje fitoresh, ananësi pozicioni dhe tabela ballë për ballë. Votat dhe përgjigjet janë skedarë JSON Lines të hapur. Me pak vota ose prompte renditja nuk thotë asgjë të përgjithshme. Alfa; të dhënat mbeten në shfletues; pa gjurmim.","tags":["IA","vlerësim"]},"calendarium":{"line":"Shkruani një datë në një nga njëmbëdhjetë kalendarët (gregorian, julian, hebre, hixhri, persian, kinez, maja, marsian…) dhe shihni në të gjithë të tjerët, me pamje mujore. Alfa; funksionon jashtë linje.","detail":"Konverton data midis njëmbëdhjetë kalendarëve (gregorian, julian, julian i rishikuar, hebraik, hixhri, persian, kopt, etiopian, kinez, maja dhe Mars Sol Date), tregon Ditën Juliane, ditën e javës dhe javën ISO, dhe ka pamje mujore me kalendar të dytë nën çdo ditë. Përfshin shënime rumune (stili i vjetër dhe i ri, kalimi i vitit 1919, Pashkët) dhe një atlas të kalendarëve, një shtojcë për çdo kalendar. Vlerat janë të llogaritura, me kufizime të deklaruara (kalendari hixhri është ai tabelor; intervalet janë të mbrojtura). Alfa, në 8 gjuhë, punon offline; pa gjurmim.","tags":["kalendarë","koha"]},"glosar":{"line":"Fjalor jashtë linje për aromanishten, meglenoromanishten dhe romanin: kërkoni pa shenja diakritike, shihni cilat fjalë bazë mungojnë dhe shtoni fjalë me burim dhe regjistër. Alfa.","detail":"Fjalorë për gjuhë të pakicave dhe të rrezikuara, ndërtuar nga folësit e tyre. Kërkon duke injoruar diakritikët, tregon besueshmërinë (skicë, me burim, i rishikuar), ka tabelë mbulimi me 50 koncepte bazë dhe ju lejon të shtoni fjalë me burim, licencë dhe regjistrim (deri në 50 KB). Eksporton skedarë TSV dhe Anki dhe një skedar kontributi për projektin. Listat fillestare janë të vogla — numërorë dhe disa fjalë, secila me burim të publikuar — dhe asnjë folës nuk i ka rishikuar ende. Alfa; punon offline; të dhënat mbeten në shfletues deri sa t’i shkarkoni.","tags":["gjuhë","fjalorë"]},"graiul":{"line":"Arkiv jashtë linje i folklorit rumun (proverba, magji, gjëegjëza, kolinda) me burim, qark dhe pëlqim. Fillon me dhjetë proverba; mund të shtoni më shumë. Alfa.","detail":"Kërkim që injoron diakritikët, me filtra sipas llojit, qarkut dhe besueshmërisë; një proverb i ditës (i njëjti për të gjithë në një datë të dhënë), hartë skematike me pllaka e 41 qarqeve dhe Bukureshtit, dhe formular shtimi që kërkon burim dhe, për magjitë dhe çdo gjë të mbledhur nga një person, një pëlqim. Eksporton një skedar kontributi dhe TSV. Të dhënat fillestare janë dhjetë proverba rumune nga Wikiquote; asnjëra nuk është rishikuar nga një folklorist. Alfa; punon offline; të dhënat mbeten në shfletues deri sa t’i shkarkoni.","tags":["folklor","arkiv"]},"indicativ-international":{"line":"Stërvituni me pyetjet e provimit të radioamatorëve me orar përsëritjeje me pesë kuti dhe provime provë me kohë; importoni paketa pyetjesh në format të përbashkët JSON. Përfshihen 50 pyetje stërvitjeje; nuk është bankë zyrtare. Alfa.","detail":"Trajner dhe simulator provimi për pyetjet e licencës së radioamatorit, me format të përbashkët paketash që çdo vend të shtojë bankën e vet. “Stërvit” përsërit përgjigjet e sakta pas 1, 3, 7, 14 dhe 30 ditësh dhe shpjegon çdo përgjigje me burimin e saj; “Provim” është test me kohë dhe prag kalimi; “Paketa” importon dhe kontrollon paketa dhe ruan kopje rezervë të progresit tuaj. Paketa e brendshme ka 50 pyetje praktike origjinale të shkruara për këtë projekt — jo bankë zyrtare — dhe ende nuk përfshihet asnjë paketë vendi. Alfa; punon offline; progresi mbetet në shfletues.","tags":["radio","provime"]},"proiector-fara-frontiere":{"line":"Telefonat në klasë bëhen ekran i përbashkët pa server dhe pa llogari: kohëmatës, sondazh, kuiz, shënime dhe tabelë; çiftim me kod QR ose tekst të ngjitur në të njëjtin rrjet. Alfa: në telefona realë ende nuk është provuar.","detail":"Ekran i përbashkët për klasën, pa server dhe pa llogari. Mësuesi hap faqen te projektori; telefoni i çdo nxënësi bashkohet duke shkëmbyer një kod (kuadro QR, foto e kodit ose tekst i ngjitur), deri në 30 telefona njëherësh. Përfshihen pesë aktivitete: kohëmatës mbrapsht, sondazh me shtylla të drejtpërdrejta, kuiz (pyetje nga skedar JSON, tekst i thjeshtë ose CSV; përgjigjja e saktë mbetet në projektor deri sa të zbulohet; bonus shpejtësie dhe tabelë pikësh), shënime ngjitëse dhe tabelë me një ngjyrë për çdo telefon. Rezultatet mund të ruhen si CSV, tekst ose PNG. Çdo aktivitet punon në një kuadër të izoluar vetëm me lejet që deklaron, dhe një aktivitet i ri është një përshkrues dhe një skript. Mësuesi mund të kyçë ose heqë një telefon dhe të mbyllë seancën; çdo pajisje zgjedh gjuhën e vet (tetë) dhe pamjen (e errët, kontrast i lartë, tekst i madh). Punon offline sapo të hapet dhe mund të instalohet. Alfa: testuar në Chromium me lidhje reale në një makinë, jo në telefona realë, shfletues të tjerë ose rrjete shkollash. Çiftëzimi kërkon të njëjtin rrjet lokal (pa ndërmjetës), ia tregon pajisjes tjetër adresën IP të secilës dhe nuk verifikon kush është pajisja tjetër. Formati i kuizit “Undava” nuk mbështetet: nuk u gjet specifikim.","tags":["klasë","projektim","kuiz"]},"regula":{"line":"Luani pesë lojëra klasike për dy (mulliri, alquerque, fanorona, mū tōrere, hnefatafl) kundër kompjuterit ose një miku; shtoni lojën tuaj si JSON. Alfa; funksionon jashtë linje.","detail":"Një motor rregullash për lojëra tradicionale me tabelë: çdo lojë është një skedar JSON, dhe teksti i rregullave në tetë gjuhë gjenerohet nga të njëjtat të dhëna që luan motori, kështu që teksti dhe loja nuk mund të ndryshojnë. Çdo palë mund të jetë person, lojtar i rastësishëm ose kompjuteri në dy nivele; zhbërje, ribërje, sugjerim dhe regjistër lëvizjesh që mund ta kopjoni. Mund të ngjitni, validoni dhe luani lojën tuaj. Lojërat janë rindërtime, jo rregulla turneu, dhe secila tregon sa të sigurta janë rregullat e saj. Alfa; punon offline; pa gjurmim.","tags":["lojëra","rregulla"]},"vietar-packs":{"line":"Shfletoni, importoni, kontrolloni dhe krijoni paketa rajonale llojesh për VietAR: emra në disa gjuhë, shenja helmueshmërie, lloje të ngjashme. Pesë draft paketa nisjeje me 71 lloje. Alfa; funksionon jashtë linje.","detail":"Paketa rajonale llojesh për VietAR: emra në disa gjuhë, shenjë toksike, ngjashmëri të rrezikshme dhe vend për foto të licencuara e lidhje zërash. Shfletoni dhe kërkoni pesë paketa fillestare (Rumania: bimë dhe kërpudha, zogj, gjitarë; Bullgaria dhe Moldavia: skelete), importoni një paketë, kontrolloni me të njëjtat rregulla si depoja, ose krijoni një për një klasë shkolle ose klub natyre. Paketat fillestare janë skica pa foto ose tinguj, dhe “jo i shënuar toksik” nuk do të thotë kurrë i ngrënshëm apo i sigurt. Aplikacioni VietAR nuk mund t’i importojë ende paketat. Alfa; punon offline.","tags":["natyrë","lloje"]},"PatruZeci":{"line":"Atlas i ilustruar dhe i animuar i përdorimeve të WD-40: udhëzues me 147 karta dhe lista zyrtare me 1993 përdorime, secila me skenën e saj të animuar. Jozyrtar, jashtë linje, pa llogari.","detail":"Atlas i ilustruar, i animuar i përdorimeve të spërkatësit WD-40 në një skedar të vetëm offline: udhëzues me 147 karta në 14 kategori (me nivel rreziku dhe çfarë bën spërkatësi), lista zyrtare “2000+ përdorime” me 1993 hyrje dhe një seksion me 25 përdorime shtesë, mite dhe paralajmërime nga artikuj uebi. 131 variante skenash të animuara, filtra sipas kategorisë dhe funksionit, ndërfaqe në 8 gjuhë. Aplikacion jozyrtar, i pavarur.","tags":["WD-40","bëje vetë"]},"ODISEEA":{"line":"Dokumentar prej rreth 4,5 minutash për Voyager 1 dhe 2 në një skedar HTML: skena të gjeneruara në kartën grafike, eksport në 2D dhe 3D për syze VR, në 8 gjuhë.","detail":"Dokumentar prej rreth 4.5 minutash për sondat Voyager 1 dhe 2, në një skedar të vetëm HTML që punon lokalisht në shfletues, pa server dhe pa instalim. Skena procedurale të gjeneruara në kartën grafike (WebGL): planetë, sondë, raketë, antena DSN, Golden Record, heliosfera, Pale Blue Dot. Imazhe publike NASA/JPL dhe Wikimedia Commons, ose imazhi juaj për çdo skenë. Eksport në 2D, 3D side-by-side gjysmë (1920×1080) dhe i plotë (3840×1080), dhe mënyrë telefoni për syza VR si VR BOX; muzikë ambientale e gjeneruar në shfletues, rrëfim opsional. Ndërfaqe, rrëfim, titra dhe kreditë në 8 gjuhë.","tags":["Voyager","dokumentar"]},"EXIF-CURAT":{"line":"Në zhvillim: mjet në Rust me analizues të sigurt për memorien për të parë dhe pastruar të dhëna të fshehura në skedarë (imazhe, PDF, Office, video: EXIF, GPS, XMP). Për momentin vetëm një skelet pre-alfa.","detail":"Punë në vazhdim: një mjet për të parë dhe hequr të dhënat e fshehura në skedarë (imazhe, PDF, Office, video: EXIF, GPS, XMP), me parsera të sigurt për kujtesën, i shkruar në Rust. Për momentin vetëm një skelet pre-alfa.","tags":["metadata","privatësi"]},"PORUMBEL":{"line":"I zhvendos automatikisht fotot e bëra me Open Camera në telefon në një dosje në kompjuter, një dosje për seancë, dhe i hap në LegatorOCR. Pa llogari, pa cloud, pa crate të palëve të treta.","detail":"Program i vogël i shkruar në Rust, pa crate të palëve të treta (Windows, macOS, Linux), që sjell në kompjuterin tuaj fotot që bëni me Open Camera: përmes Wi-Fi (faqe ngarkimi ose WebDAV, me kod QR), përmes ADB (USB ose Wi-Fi) ose nga një dosje e sinkronizuar (Syncthing etj.). I rendit fotot në një dosje për çdo seancë xhirimi dhe e hap çdo seancë të përfunduar në LegatorOCR (ndarje, drejtim, prerje, PDF me OCR). Panel kontrolli lokal dhe komandë “porumbel doctor” për diagnostikim; asgjë nuk del nga rrjeti juaj. Version 0.x; licencë MIT.","tags":["foto","transferim"]},"colibri-companion":{"line":"Aplikacion desktop miqësor për motorin lokal të inferencës colibri: zgjidhni një model që i përshtatet kompjuterit tuaj, shkarkojeni me një klikim dhe bisedoni me të. Pa llogari, pa shërbim cloud.","detail":"Aplikacion desktop i shkruar në Rust për colibri (JustVugg/colibri): gjen Python dhe colibri, tregon vetëm modelet që përshtaten me kujtesën e kompjuterit tuaj, i shkarkon me pauzë dhe vazhdim, nis serverin lokal dhe hap bisedën (përgjigje në transmetim, Markdown, biseda të ruajtura, kërkim, dokumente lokale dhe mjete MCP me miratim në çdo thirrje). Paneli Resurset tregon procesorin, kujtesën, kartën grafike dhe lidhjet e hapura. Windows, macOS, Linux; ndërfaqe në 8 gjuhë; licencë Apache-2.0.","tags":["IA lokale","desktop"]},"CartaColibri":{"line":"Bibliotekë lokale IA mbi motorin Colibrì: indekson dosjet që zgjidhni, kërkon menjëherë dhe i kërkon një modeli lokal të përmbledhë, nxjerrë të dhëna ose sintetizojë, duke treguar gjithmonë skedarin burimor. Asgjë nuk e lë kompjuterin tuaj.","detail":"Program i shkruar në Rust, me faqe lokale (127.0.0.1) dhe linjë komande. Indekson dosjet që zgjidhni (origjinalet vetëm lexohen, kurrë nuk ndryshohen), kërkon në tekstin e plotë (fjalë, “fraza”, prefiks*, AND/OR/NOT, filtra sipas llojit, madhësisë, vendndodhjes) dhe grupon skedarët. Një model lokal Colibrì përmbledh, nxjerr (tabelë ose JSON, “NOT FOUND” në vend të hamendjeve), sintetizon ose krahason, gjithmonë me burime të cituara [S1], [S2] dhe rezultat bazimi. Ka edhe shfletuesin e vogël web-grab, një server MCP vetëm për lexim, importe (faqeshënues, Obsidian, Zotero, RSS) dhe kontroll të tekstit tuaj kundrejt bibliotekës. Pa llogari, pa telemetri; ndërfaqe në 8 gjuhë; version alfa 0.2; licencë MIT.","tags":["IA lokale","bibliotekë"]},"PolyTabletop":{"line":"240 lojëra tavoline kundër kompjuterit në terminal ose dritare grafike, plus lojë për dy në të njëjtën tastierë ose përmes rrjetit. Shkruar në Rust; motori dhe lojërat nuk kanë varësi të jashtme.","detail":"Koleksion clean-room lojërash tavoline i shkruar në Rust: 240 lojëra të luajtshme kundër kompjuterit, në terminal ose në dritare grafike, plus lojë hot-seat dhe lojë në rrjet për dy lojtarë. Klasikë abstraktë, lojëra me letra dhe zare, variante origjinale të mekanikave moderne me emra të vetë, lojëra kooperative me partner AI, lojëra me role të fshehura, lojëra festash dhe fjalësh; katalogu ka 1200 hyrje, me një paketë mjetesh për lojëra me role (zare, fleta, gjenerues birucash, simulator betejash). Kundërshtar AI (alfa-beta, MCTS), arenë AI kundër AI, transkriptime dhe riluajtje. Ndërfaqe në 8 gjuhë; version 0.9; licencë MIT ose Apache-2.0.","tags":["lojëra tavoline","Rust"]},"STRAJA":{"line":"Mburojë kundër agjentëve IA që lexojnë telefonin tuaj: tregon cilat aplikacione mund të lexojnë njoftimet, ekranin, fotot dhe SMS-të tuaja, paralajmëron kur një e re merr akses dhe ju çon te cilësimi ku e revokoni lejen. Pa llogari, pa leje INTERNET.","detail":"Aplikacion për Android (APK) dhe iPhone (IPA i pa nënshkruar). Në Android liston aplikacionet me akses në njoftime, shërbime aksesueshmërie, rolin e asistentit dhe leje për media e SMS, me rezultat rreziku për çdo aplikacion dhe për të gjithë telefonin; një monitor periodik krahason telefonin me një bazë dhe ju njofton për çdo akses të ri. Hap faqen e saktë të cilësimeve të sistemit për të revokuar një akses dhe nuk ndryshon asgjë në heshtje. Akses i përkohshëm me kujtesë dhe udhëzues mbrojtjeje me 12 pika. Në iPhone nuk ka auditim (iOS fsheh lejet e aplikacioneve të tjera), vetëm udhëzuesi, një regjistër manual dhe kujtesa. Nuk mund ta ndalojë një agjent. Pa leje INTERNET, pa kopje rezervë; 8 gjuhë; version 1.0; licencë MIT.","tags":["privatësi","telefon"]},"CUPLAJ":{"line":"Telefoni me linjë të përbashkët për teatër zhytës: një flotë telefonash të zakonshëm Android bëhet central privat përmes Wi-Fi-t të vendit; pa cloud, pa llogari, pa reklama. Tipari dallues është «cuplaj»: linja e përbashkët e telefonave fiks nga vitet 1980 deri rreth 2006.","detail":"Aplikacion Android (APK) dhe aplikacion iPhone/iPad (IPA i pa nënshkruar). Organizatorët dhe aktorët u flasin shikuesve përmes Wi-Fi lokal; një telefon (kontrolli) është centrali. Gjashtë epoka telefonike (1985 me disk, 1995 me tastierë, 2003 celular, 2025 smartphone, 2045 veshëse, 2080 mendje e përbashkët), linja e përbashkët ku dy abonentë ndajnë një linjë, thirrje reale, sistem njoftimi push-to-talk, kanal prapaskene, sinjale (tekst në ekran të plotë, dridhje, zile, blic, zë i folur, thirrje fantazmë) dhe skenar me GO dhe PLAY. Pa infrastrukturë, çelës rrjeti AES-128-GCM opsional, thirrje P2P të drejtpërdrejta. Pa analitikë, pa serverë, pa llogari. 8 gjuhë; version 1.10; licencë MIT.","tags":["teatër zhytës","telefoni"]},"LUSTRUM":{"line":"Rikthejeni hapësirën në telefon: gjen skedarë të panevojshëm, dublikatë, foto të ngjashme dhe mbetje aplikacionesh dhe i pastron vetëm me pëlqimin tuaj. Nuk ka leje INTERNET, ndaj fizikisht nuk mund të dërgojë asgjë askund.","detail":"Aplikacion Android (Kotlin). Ruajtje sipas llojit të skedarit, skedarë të mëdhenj, të vjetër dhe mbeturinë, dublikatë të saktë (madhësi, shenjë gishti e shpejtë, pastaj SHA-256), foto të ngjashme (hashing perceptual), mbetje të aplikacioneve të çinstaluara, kompresim JPEG, cache, foto të paqarta dhe të errëta, një Swiper (majtas = fshi, djathtas = mbaj), pastrim i planifikuar dhe një kosh 30-ditor LUSTRUM për zhbërje. Pa leje INTERNET: asgjë nuk del nga telefoni. Pa magji në nivel root: Android 11+ i mban të gjitha aplikacionet normale jashtë dosjeve të të dhënave të aplikacioneve të tjera. 8 gjuhë (përkthime të bëra me makinë); version beta 0.8; licencë MIT.","tags":["pastrues telefoni","Android"]},"STENOGRAMA":{"line":"Transkriptim i audios së gjatë drejtpërdrejt në shfletues me Whisper lokal: një skedar HTML, pa llogari, pa server, pa filigran. Audioja juaj nuk e lë kurrë pajisjen; shkarkohet vetëm modeli Whisper, një herë.","detail":"Lexon MP3 dhe WAV në pjesë (kështu gjatësia nuk kufizohet nga kujtesa); formatet e tjera (M4A, OGG/Opus, MP4, FLAC) dekodohen të plota. Çdo fetë pritet në një pauzë që fjalët të mos ndahen; progresi ruhet, kështu mund të ndaloni dhe të vazhdoni. Redaktor brenda faqes (klikoni një kohë për të dëgjuar vendin), heqje e frazave fantazmë tipike të Whisper, eksport në .txt, .srt, .vtt, .docx ose në clipboard. Përdor WebGPU kur disponohet, përndryshe procesorin (WASM). PWA e instalueshme; modeli mbetet në cache pas shkarkimit të parë. Biblioteka ngarkohet nga jsDelivr në transkriptimin e parë, e kontrolluar me SHA-384. Ndërfaqe në 7 gjuhë; licencë MIT.","tags":["transkriptim","audio"]},"GERMEN":{"line":"Stërvitni një model të vogël gjuhësor nga e para në Rust të pastër në një procesor të zakonshëm: pa Python, pa CUDA, pa llogari, pa qasje në rrjet, pa telemetri. Një binar, një skedar teksti, një komandë.","detail":"Program Rust (mbi Burn, me backend-in e tij CPU në Rust të pastër) që stërvit një rrjet të stilit GPT mbi bajte ose mbi një fjalor BPE të mësuar nga teksti juaj, pastaj gjeneron tekst nga modeli i stërvitur. GERMEN Studio: një dritare lokale (127.0.0.1) me kurbën e humbjes, shpejtësinë dhe mostra teksti, në 8 gjuhë. Komanda për të matur shpejtësinë e kompjuterit tuaj dhe për të kontrolluar e riparuar skedarët e modelit. Është një punishte për mësim dhe eksperimentim, jo fabrikë chatbot-esh: një model prej 1–25 milionë parametrash mëson formën e një teksti, jo njohuri për botën. Pa GPU, pa saktësi të përzier. Version 0.6; licencë MIT.","tags":["IA lokale","Rust"]},"CUANTOR":{"line":"Simulator i kompjuterit kuantik për desktopin tuaj, nga 5 deri në 1000 kubite, me ndërfaqe në stilin e IBM Quantum Composer. Matematikë e saktë, por jo harduer i vërtetë kuantik.","detail":"Program Rust në katër pjesë (bërthama, dritarja, linja e komandës, lidhja IBM) për Windows, macOS dhe Linux. Një tabelë vizatimi si Composer i IBM: vendosni porta me ngjyra në linja (kubite) dhe shikoni shtylla dhe një sferë që tregojnë rezultatin, ndërsa një panel teksti shkruan të njëjtin qark drejtpërdrejt në OpenQASM dhe Qiskit. Tri kalkulatorë: një që kujton çdo numër (deri në 28 kubite), një shumë i shpejtë për porta të thjeshta (deri në 4096) dhe një për qarqe me pak degëzime. Matje, reset dhe if në mes të ekzekutimit, portat tuaja, zhurmë e simuluar, rezultate të përsëritshme me një farë. Lexon OpenQASM 2.0 dhe 3.0; mund ta hapni qarkun në IBM Composer ose ta dërgoni në një makinë reale IBM me çelësin e llogarisë suaj (e paverifikuar në harduer real IBM). Ndërfaqe në 8 gjuhë; version 0.2.","tags":["kompjuter kuantik","simulator"]},"ERATA":{"line":"Korrektues në shfletues që kontrollon drejtshkrimin, gramatikën, pikësimin dhe tipografinë drejt në kompjuterin tuaj: pa llogari, pa server, pa telemetri. Më i thelli për rumanishten.","detail":"Shtesë për Chromium dhe Firefox (versioni për Safari i patestuar), e shkruar nga zero pa kod, rregulla ose të dhëna nga LanguageTool apo ndonjë kontrollues tjetër. Punon në fushat textarea, input dhe contenteditable dhe vizaton nënvizimet pa ndryshuar faqen. Zbulon gjuhën për çdo paragraf, rikthen diakritikët (ro, fr, es, pt) vetëm kur korrigjimi është i pakundërshtueshëm, dhe ka rregulla të thella për rumanishten (presje poshtë ș/ț, “să/sa”, “într-un”, presja para “dar/însă”). Fjalor personal, rregulla të personalizuara, çelës për çdo faqe, import fjalorësh Hunspell. Rishkrim opsional përmes një modeli lokal (vetëm localhost, i çaktivizuar si parazgjedhje). Ndërfaqe në 25 gjuhë. Version 0.4; licencë MIT.","tags":["korrektues","shtesë"]}});
